import json,csv,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[6];OUT=Path(__file__).resolve().parent;BASE=ROOT/'research/mace-v12-transfer/periodic_interface_v4';WB=OUT.parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
v17=BASE/'mace_periodic_v17_interface_energy';p16=BASE/'pbe_interface_v17_main_targeted_acquisition/development_validation_evaluation_v16/evaluation.json';p17=v17/'evaluation_dev_01/evaluation.json';ps=v17/'training_provisional_03/selection_record.json'
a=json.loads(p16.read_text());b=json.loads(p17.read_text());s=json.loads(ps.read_text());assert s['selected_epoch']==79 and s['completed_epochs']==80 and s['training_exit_code']==0
pins={str(p.relative_to(ROOT)):sha(p) for p in [p16,p17,ps,WB/'v9_v16_cross_version_root_cause_review/report.md']}
for p,h in [(ROOT/s['model_path'],s['model_sha256']),(ROOT/a['model_path'],a['model_sha256']),(v17/'data/train.extxyz',s['training_input_sha256']),(v17/'data/dataset_manifest.json',s['dataset_manifest_sha256']),(ROOT/s['training_log_path'],s['training_log_sha256'])]:
 assert sha(p)==h; pins[str(p.relative_to(ROOT))]=h
assert sha(ps)==b['selection_record_sha256'] and s['model_sha256']==b['model_sha256']
rows=[]
metrics=['energy_abs_error_meV_atom','force_vector_RMSE_eV_A','separating_force_abs_error_eV_A','force_vector_max_error_eV_A']
for x,y in zip(a['per_structure'],b['per_structure']):
 assert x['label']==y['label'] and x['reference_sha256']==y['reference_sha256']
 p=BASE/'pbe_interface_v17_main_targeted_acquisition/development_validation_archives'/x['label']/(x['label']+'_PW_PBE.extxyz');assert sha(p)==x['reference_sha256'];pins[str(p.relative_to(ROOT))]=sha(p)
 for k in metrics:rows.append({'interface':x['interface'],'metric':k,'V16':x[k],'V17':y[k],'delta_V17_minus_V16':y[k]-x[k],'reduction_percent':100*(x[k]-y[k])/x[k]})
with (OUT/'matched_metrics.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
(OUT/'review.json').write_text(json.dumps({'source_hashes':pins,'matched_metrics':rows,'selection':s,'V17_status':b['status'],'same_three_development_structures':True,'V17_per_atom_projection_available':False,'no_new_inference':True},indent=2)+'\n')
lines=['# V9–V17 cumulative review and matched V16/V17 development comparison','','|Interface|Vector RMSE V16 → V17|Separation error V16 → V17|','|---|---|---|']
for x,y in zip(a['per_structure'],b['per_structure']):lines.append(f"|{x['interface']}|{x['force_vector_RMSE_eV_A']:.5f} → {y['force_vector_RMSE_eV_A']:.5f}|{x['separating_force_abs_error_eV_A']:.5f} → {y['separating_force_abs_error_eV_A']:.5f}|")
lines+=['','All three vector RMSEs improve but remain above0.05 eV/A. AgC separation improves and passes0.10; AgSi improves but fails; AgTi separation worsens and fails. AgTi maximum atom error also worsens despite lower aggregate RMSE. All energies improve and pass10 meV/atom. Overall remains FAIL. References/model/data/epoch79 selection hashes checked exactly. These are reused development structures, not fresh blind tests.','','## Cumulative evidence and limits','Reuse the hash-pinned V9–V16 report: local transverse/framework coverage remained the leading actionable hypothesis, provenance uncertainty a separate risk, historical roles/metrics limit comparisons, and no controlled optimizer ablation proved a parameter cause. V17 adds eight signed local diagnostics; matched aggregate improvements support a useful coverage contribution but do not isolate causation. Selection policy changed to fixed epoch79 and earlier runs had checkpoint-export issues, so this is not a perfectly isolated data-only experiment. The earlier claim of12 additional declaration-only rows is superseded by original archive reconciliation: current pool has29 direct and14 partial.','','V16 localization identifies AgC Ti604600 transverse response, AgSi framework/Ag transverse neighbors, and AgTi Ti479027–C480805 shell response. V17 published evaluation contains only aggregate/max metrics, no per-atom prediction vectors. Therefore V17 spatial, transverse and framework changes cannot be reconstructed without forbidden new inference; do not transplant V16 atom identities onto V17 maxima.','','## V18 recommendations, ordered by evidence','1. Maintain gates and record AgTi separation/max regression as an explicit target. Obtain/publish V17 development per-atom diagnostics from existing A artifacts if available before choosing perturbation directions. Do not infer one cause from aggregate errors.','2. Prepare the directly supported30-frame proposal (core29 plus exact frame0 relabel) and let A decide a provenance/data-membership comparison with fixed recipe and the same development references. This removes14 partial frames but changes coverage and adds a mesh-changed relabel, so an error difference cannot establish label inconsistency alone. Gamma convergence of short frame0 directions is unresolved.','3. If coverage-driven augmentation is chosen, prioritize paired AgTi marked Ti/framework-C and AgC transverse Ti-shell environments; keep prior paired signs and new training roles explicit. Require fresh held-out family after development tuning, without opening current sealed tests for choice.','4. No evidence presently identifies a better learning rate or force weight. Preserve seed45, medium foundation, batch1, lr1e-4, wd5e-7, energy100/force1000 and80 epochs for the minimum next controlled comparison. Do not vary data, weights and epoch policy together.','','Minimum controlled follow-up for A review: one clean30-versus-provisional43 fixed-recipe comparison, reporting vector/max/separation on the same development set, provenance/mesh caveats and coverage removals; not an authorized training launch. No claim of thermal/morphology applicability and no MD/TTM.']
(OUT/'report.md').write_text('\n'.join(lines)+'\n');(OUT/'SHA256SUMS.txt').write_text(''.join(f'{sha(p)}  {p.name}\n' for p in sorted(OUT.iterdir()) if p.is_file() and p.name!='SHA256SUMS.txt'));print('matched metrics and hash checks PASS')
